private const val REQUEST_ERROR_SNIPPET = 400

/**
 * Typed client of the daemon's native surface. One instance per daemon
 * connection; [bearerToken] is the connection password and never logged.
 */
class NativeClient(
    val baseUrl: String,
    val bearerToken: String,
    private val timeoutMs: Long = DEFAULT_TIMEOUT_MS,
    private val maxBodyBytes: Long = DEFAULT_MAX_BODY_BYTES,
    /**
     * The control-plane credential (`x-faktor-control-token`): an auth-session
     * or service-account token, NEVER the daemon password. Absent = no
     * control-plane principal; the billing/identity routes then refuse loudly
     * and the usage panel renders that refusal (never fabricated numbers).
     */
    private val controlToken: String? = null
) {
    companion object {
        const val DEFAULT_TIMEOUT_MS = 15_000L
        const val DEFAULT_MAX_BODY_BYTES = 4L * 1024 * 1024
        const val EVIDENCE_MAX_BODY_BYTES = 32L * 1024 * 1024
        const val READY_POLL_MS = 100L

        fun forConnection(
            connection: BackendConnection,
            controlToken: String? = null,
            // Submitting a prompt starts real work (candidate prep,
            // verification, integration); the 15 s default read timeout can
            // expire on a loaded machine even though the run is healthy.
            // Long-operation callers pass a generous budget.
            timeoutMs: Long = DEFAULT_TIMEOUT_MS
        ): NativeClient =
            NativeClient(
                connection.baseUrl,
                connection.password,
                timeoutMs = timeoutMs,
                controlToken = controlToken
            )
    }

    private val http: HttpClient = HttpClient.newBuilder()
        .connectTimeout(Duration.ofMillis(timeoutMs))
        .build()

    // ------------------------------------------------------------ liveness

    fun health(): NativeHealth = parseNativeHealth(request("GET", "/native/health"))

    fun ready(): NativeReady = parseNativeReady(request("GET", "/native/ready"))

    /** Polls readiness until true or the deadline; returns the last ready state. */
    fun awaitReady(timeoutMs: Long = 10_000L): NativeReady {
        val deadline = System.currentTimeMillis() + timeoutMs
        var last = NativeReady(false)
        while (System.currentTimeMillis() < deadline) {
            last = try {
                ready()
            } catch (e: NativeApiException) {
                if (e.status != 503) throw e
                NativeReady(false)
            }
            if (last.ready) return last
            Thread.sleep(READY_POLL_MS)
        }
        return last
    }

    // ------------------------------------------------------------- sessions

    fun createSession(
        provider: String,
        model: String,
        workspace: String? = null,
        title: String? = null
    ): NativeSessionCreated = parseNativeSessionCreated(
        request(
            "POST", "/native/session", null,
            NativeRequests.createSession(provider, model, workspace, title)
        )
    )

    fun listSessions(): List<NativeSessionSummary> =
        parseNativeSessionList(request("GET", "/native/sessions"))

    fun modelCatalog(): List<NativeModelInfo> =
        parseNativeModelCatalog(request("GET", "/models"))

    fun prompt(sessionId: String, prompt: String, files: List<String>? = null): NativePromptReceipt =
        parseNativePromptReceipt(
            request(
                "POST", "/native/session/" + encode(sessionId) + "/prompt", null,
                NativeRequests.prompt(sessionId, prompt, files)
            )
        )

    fun abortSession(sessionId: String, opId: String? = null): NativeAbortAck =
        parseNativeAbortAck(
            request(
                "POST", "/native/session/" + encode(sessionId) + "/abort", null,
                NativeRequests.abort(sessionId, opId)
            )
        )

    fun projection(sessionId: String): NativeProjection =
        parseNativeProjection(
            request("GET", "/session/" + encode(sessionId) + "/projection")
        )

    fun messages(sessionId: String, before: Long? = null, limit: Long? = null): NativeMessagePage =
        parseNativeMessagePage(
            request(
                "GET", "/native/messages",
                query("session" to sessionId, "before" to before?.toString(), "limit" to limit?.toString())
            )
        )

    fun events(sessionId: String, after: Long? = null, limit: Long? = null): NativeEventPage =
        parseNativeEventPage(
            request(
                "GET", "/native/events",
                query("session" to sessionId, "after" to after?.toString(), "limit" to limit?.toString())
            )
        )

    // ------------------------------------------------------------ task runs

    fun taskRuns(sessionId: String): List<NativeTaskRun> = parseNativeTaskRuns(
        request("GET", "/native/session/" + encode(sessionId) + "/task-runs")
    )

    fun taskRunState(sessionId: String, runId: String): NativeTaskRun {
        val runs = taskRuns(sessionId)
        for (run in runs) {
            if (run.runId == runId) return run
        }
        throw NativeApiException(404, "not_found", "task run $runId under session $sessionId", false)
    }

    fun startTaskRun(
        sessionId: String,
        goal: String,
        criteria: List<String>? = null,
        model: String? = null,
        maxTokens: Long? = null,
        maxCostMicro: BigInteger? = null,
        mutationMode: String? = null,
        files: List<String>? = null,
        completionContract: NativeCompletionContract? = null
    ): NativeTaskRunStarted = parseNativeTaskRunStarted(
        request(
            "POST", "/native/session/" + encode(sessionId) + "/task-runs", null,
            NativeRequests.startTaskRun(
                goal, criteria, model, maxTokens, maxCostMicro, mutationMode, files,
                completionContract
            )
        )
    )

    fun cancelTaskRun(sessionId: String, runId: String): NativeTaskRunCancelled =
        parseNativeTaskRunCancelled(
            request(
                "POST",
                "/native/session/" + encode(sessionId) + "/task-runs/" + encode(runId) + "/cancel"
            )
        )

    fun taskViews(sessionId: String): List<NativeTaskView> = parseNativeTaskViews(
        request("GET", "/native/session/" + encode(sessionId) + "/tasks")
    )

    // ------------------------------------------------------ coordination board

    /**
     * One bounded newest-first page of the path session's run-family board.
     * `since` is the exclusive cursor for the next OLDER page (the value a
     * previous page returned as `next_before_revision`).
     */
    fun board(sessionId: String, since: Long? = null, limit: Long? = null): NativeBoardPage =
        parseNativeBoardPage(
            request(
                "GET", "/native/session/" + encode(sessionId) + "/board",
                query("since" to since?.toString(), "limit" to limit?.toString())
            )
        )

    /** Append one bounded post AS the session (201); the server is the guard. */
    fun boardPost(
        sessionId: String,
        subject: String,
        body: String,
        refs: List<String>? = null
    ): NativeBoardPost = parseNativeBoardPost(
        request(
            "POST", "/native/session/" + encode(sessionId) + "/board", null,
            NativeRequests.boardPost(subject, body, refs)
        )
    )

    // ------------------------------------------------------------ tournaments

    fun startTournament(
        sessionId: String,
        goal: String,
        criteria: List<String>,
        n: Int,
        model: String? = null,
        maxTokens: Long? = null,
        maxCostMicro: BigInteger? = null,
        mutationMode: String? = null,
        files: List<String>? = null
    ): NativeTournamentStarted = parseNativeTournamentStarted(
        request(
            "POST", "/native/session/" + encode(sessionId) + "/tournament", null,
            NativeRequests.startTournament(
                goal, criteria, n, model, maxTokens, maxCostMicro, mutationMode, files
            )
        )
    )

    fun tournamentState(sessionId: String, tournamentId: String): NativeTournament =
        parseNativeTournament(
            request(
                "GET",
                "/native/session/" + encode(sessionId) + "/tournament/" + encode(tournamentId)
            )
        )

    /** The durable tournament listing of one session (newest last). */
    fun tournaments(sessionId: String): List<NativeTournamentSummary> =
        parseNativeTournamentSummaries(
            request("GET", "/native/session/" + encode(sessionId) + "/tournaments")
        )

    /** Run the deterministic comparison; engine refusals are typed (404/409). */
    fun decideTournament(sessionId: String, tournamentId: String): NativeTournamentDecision =
        parseNativeTournamentDecision(
            request(
                "POST",
                "/native/session/" + encode(sessionId) + "/tournaments/" +
                    encode(tournamentId) + "/decide",
                null,
                NativeRequests.decideTournament()
            )
        )

    /** Abort one tournament with an optional reason; returns the durable state. */
    fun abortTournament(
        sessionId: String,
        tournamentId: String,
        reason: String? = null
    ): NativeTournament = parseNativeTournament(
        request(
            "POST",
            "/native/session/" + encode(sessionId) + "/tournaments/" +
                encode(tournamentId) + "/abort",
            null,
            NativeRequests.abortTournament(reason)
        )
    )

    // ------------------------------------------------------- orchestrator graph

    fun orchestratorGraph(sessionId: String): NativeOrchestratorGraph =
        parseNativeOrchestratorGraph(
            request("GET", "/native/orchestrator/graph", query("session" to sessionId))
        )

    // ------------------------------------------------- permissions (reply path)

    fun permissions(sessionId: String): List<NativePermissionEntry> =
        parseNativePermissionList(
            request("GET", "/native/permissions", query("session" to sessionId))
        )

    fun replyPermission(permissionId: String, decision: String): NativePermissionAck =
        parseNativePermissionAck(
            request(
                "POST", "/native/permission/reply", null,
                NativeRequests.permissionReply(permissionId, decision)
