    // ------------------------------------------------- provider registry (P0-64)

    /** The registered provider instances with their known models. */
    fun providers(): List<NativeProviderInfo> =
        parseNativeProviders(request("GET", "/native/providers"))

    // ---------------------------------------------------- terminals (P0-62)

    /**
     * The session-scoped terminal projection. Only terminals durably owned by
     * [sessionId] appear; unowned legacy rows are counted in `unowned` and
     * named in `note` instead of leaking into the view.
     */
    fun terminals(sessionId: String): NativeTerminalPage =
        parseNativeTerminalPage(
            request("GET", "/native/terminals", query("session" to sessionId))
        )

    /** One bounded page of the session's terminal lifetime events. */
    fun terminalEvents(
        sessionId: String,
        after: Long? = null,
        limit: Long? = null
    ): NativeTerminalEventPage = parseNativeTerminalEventPage(
        request(
            "GET",
            "/native/session/" + encode(sessionId) + "/terminal/events",
            query("after" to after?.toString(), "limit" to limit?.toString())
        )
    )

    /** Spawn one session-owned terminal; strict body, server owns the bounds. */
    fun spawnTerminal(
        sessionId: String,
        command: String,
        args: List<String>? = null,
        cwd: String? = null,
        rows: Long? = null,
        cols: Long? = null
    ): NativeTerminalSpawned = parseNativeTerminalSpawned(
        request(
            "POST", "/native/session/" + encode(sessionId) + "/terminal", null,
            NativeRequests.spawnTerminal(command, args, cwd, rows, cols)
        )
    )

    /** Snapshot available output of one PTY (does not drain the buffer). */
    fun terminalOutput(sessionId: String, terminalId: String): NativeTerminalOutput =
        parseNativeTerminalOutput(
            terminalId,
            request(
                "GET",
                "/native/session/" + encode(sessionId) + "/terminals/" +
                    encode(terminalId) + "/output"
            )
        )

    // --------------------------------------------------------------- agents

    fun agents(sessionId: String): List<NativeAgent> = parseNativeAgents(
        request("GET", "/native/agents", query("session" to sessionId))
    )

    fun pauseAgent(childId: String): NativeAgentControlAck = agentControl(childId, "pause")

    fun resumeAgent(childId: String): NativeAgentControlAck = agentControl(childId, "resume")

    fun cancelAgent(childId: String): NativeAgentControlAck = agentControl(childId, "cancel")

    fun retryAgent(childId: String): NativeAgentControlAck = agentControl(childId, "retry")

    fun steerAgent(childId: String, text: String): NativeAgentControlAck =
        parseNativeAgentControlAck(
            request(
                "POST", "/native/agents/" + encode(childId) + "/steer", null,
                NativeRequests.steer(text)
            )
        )

    fun setAgentModel(childId: String, model: String): NativeAgentControlAck =
        parseNativeAgentControlAck(
            request(
                "POST", "/native/agents/" + encode(childId) + "/model", null,
                NativeRequests.changeModel(model)
            )
        )

    fun setAgentBudget(
        childId: String,
        maxTokens: Long? = null,
        maxCostMicro: BigInteger? = null
    ): NativeAgentControlAck {
        if ((maxTokens == null) == (maxCostMicro == null)) {
            throw NativeProtocolException(
                "setAgentBudget",
                "exactly one of maxTokens or maxCostMicro must be set"
            )
        }
        return parseNativeAgentControlAck(
            request(
                "POST", "/native/agents/" + encode(childId) + "/budget", null,
                NativeRequests.changeBudget(maxTokens, maxCostMicro)
            )
        )
    }

    /**
     * Durable presentation/attention transition of one child of
     * [sessionId]: `foreground` shows the child in the main tree,
     * `background` dims/tucks it. The server owns the terminal-child
     * refusal (typed 409) and the idempotent same-state no-op.
     */
    fun setAgentPresentation(
        sessionId: String,
        childId: String,
        presentation: String
    ): NativePresentationAck = parseNativePresentationAck(
        request(
            "POST",
            "/native/session/" + encode(sessionId) + "/agents/" + encode(childId) +
                "/presentation",
            null,
            NativeRequests.changePresentation(presentation)
        )
    )

    private fun agentControl(childId: String, action: String): NativeAgentControlAck =
        parseNativeAgentControlAck(
            request("POST", "/native/agents/" + encode(childId) + "/" + action)
        )

    // ------------------------------------------------------ usage / verification

    fun usage(): NativeUsageTotals = parseNativeUsage(request("GET", "/native/usage"))

    fun sessionUsage(sessionId: String): NativeSessionUsage = parseNativeSessionUsage(
        request("GET", "/native/session/" + encode(sessionId) + "/usage")
    )

    // ------------------------------------------------- commercial metering

    /** The caller's control-plane identity (fixes the billing organization). */
    fun identity(): NativeIdentity = parseNativeIdentity(request("GET", "/native/identity"))

    /** The derived entitlement snapshot of the caller's organization. */
    fun entitlements(): NativeEntitlementSnapshot =
        parseNativeEntitlements(request("GET", "/native/entitlements"))

    /**
     * The organization's usage fold plus ONE cursor page of its usage events.
     * `since` is the exclusive cursor a previous page returned as
     * `nextCursor`; the daemon bounds the page size (1..=200).
     */
    fun billingUsage(
        organization: String,
        since: String? = null,
        limit: Long? = null
    ): NativeBillingUsage = parseNativeBillingUsage(
        request(
            "GET", "/native/usage",
            query(
                "org" to organization,
                "since" to since,
                "limit" to limit?.toString()
            )
        )
    )

    /**
     * Grant credits (admin role only; the server is the guard). The daemon
     * REQUIRES the `Idempotency-Key` header: the same key + same request
     * replays the recorded result instead of appending a second grant.
     */
    fun grantCredits(
        amountMicro: BigInteger,
        idempotencyKey: String,
        reason: String? = null,
        accountId: String? = null
    ): NativeCreditGrant = parseNativeCreditGrant(
        request(
            "POST", "/native/credits/grant", null,
            NativeRequests.grantCredits(amountMicro, reason, accountId),
            maxBodyBytes,
            listOf(Pair("idempotency-key", idempotencyKey))
        )
    )

    /**
     * Revoke the caller's control-plane session (`POST /native/sso/logout`).
     * The route needs the daemon password (the bearer this client always
     * sends) AND the session's own token (`x-faktor-control-token`), plus the
     * STRICT body `{organization, session_id}` naming the session the token
     * must own. The session id is a NON-secret coordinate provisioned with
     * the credential; the token is never derivable from it. Server refusals
     * are typed: foreign/missing session 404, non-owning token 401, disabled
     * control plane 409 — the caller reports the refusal and the local
     * credential is still removed (never a claimed revoke).
     */
    fun revokeControlSession(organization: String, sessionId: String) {
        if (organization.isBlank() || sessionId.isBlank()) {
            throw NativeProtocolException(
                "POST /native/sso/logout",
                "revoking a control-plane session requires the organization and the auth-session id"
            )
        }
        request(
            "POST", "/native/sso/logout", null,
            NativeRequests.ssoLogout(organization, sessionId)
        )
    }

    fun verification(sessionId: String): NativeVerificationView = parseNativeVerificationView(
        request("GET", "/native/session/" + encode(sessionId) + "/verification")
    )

    fun taskVerification(sessionId: String, taskId: String): NativeTaskVerification =
        parseNativeTaskVerification(
            request(
                "GET",
                "/native/session/" + encode(sessionId) + "/tasks/" + encode(taskId) + "/verification"
            )
        )

    /**
     * The strict proof summary (`GET /native/tasks/{id}/proof`), session
     * scoped by the REQUIRED `session` query. Read-only and fail-closed: a
     * corrupt store read is a typed API error the caller renders as an
     * explicit unavailable state, never as VERIFIED.
     */
    fun taskProof(sessionId: String, taskId: String): NativeTaskProof =
        parseNativeTaskProof(
            request(
                "GET", "/native/tasks/" + encode(taskId) + "/proof",
                query("session" to sessionId)
            )
        )

    /** The durable per-step status/report read (proof drill-down). */
    fun taskCompletionSteps(sessionId: String, taskId: String): NativeTaskCompletionSteps =
        parseNativeTaskCompletionSteps(
            request(
                "GET", "/native/tasks/" + encode(taskId) + "/completion-steps",
                query("session" to sessionId)
            )
        )

    // ------------------------------------------------------------- evidence

    fun evidence(sessionId: String, evidenceId: Long): NativeEvidence = parseNativeEvidence(
        request(
            "GET", "/native/evidence/" + evidenceId,
            query("session" to sessionId)
        )
    )

    fun retrieveEvidence(
        sessionId: String,
        evidenceId: Long,
        selectorJson: String
    ): NativeEvidenceRetrieval = parseNativeEvidenceRetrieval(
        request(
            "POST", "/native/evidence/" + evidenceId + "/retrieve",
            query("session" to sessionId), selectorJson,
            EVIDENCE_MAX_BODY_BYTES
        )
    )

    // ------------------------------------------------------------- transport

    private fun query(vararg pairs: Pair<String, String?>): List<Pair<String, String>> {
        val out = ArrayList<Pair<String, String>>()
        for (pair in pairs) {
            if (pair.second != null) out.add(Pair(pair.first, pair.second!!))
        }
        return out
    }

    private fun encode(value: String): String = URLEncoder.encode(value, "UTF-8")

    private fun request(
        method: String,
        path: String,
        queryParams: List<Pair<String, String>>? = null,
        body: String? = null,
        maxBytes: Long = maxBodyBytes,
        extraHeaders: List<Pair<String, String>>? = null
    ): String {
        val url = StringBuilder(baseUrl.trimEnd('/')).append(path)
        if (queryParams != null && queryParams.isNotEmpty()) {
            url.append('?')
            for ((i, pair) in queryParams.withIndex()) {
                if (i > 0) url.append('&')
                url.append(encode(pair.first)).append('=').append(encode(pair.second))
            }
        }
        val builder = HttpRequest.newBuilder(URI.create(url.toString()))
            .timeout(Duration.ofMillis(timeoutMs))
            .header("Authorization", "Bearer $bearerToken")
            .header("Accept", "application/json")
        if (controlToken != null && controlToken.isNotEmpty()) {
            builder.header("x-faktor-control-token", controlToken)
        }
        if (extraHeaders != null) {
            for (header in extraHeaders) {
                builder.header(header.first, header.second)
            }
        }
        if (body != null) {
            builder.header("Content-Type", "application/json")
            builder.method(method, HttpRequest.BodyPublishers.ofString(body))
        } else {
            builder.method(method, HttpRequest.BodyPublishers.noBody())
        }
        val response = try {
            http.send(builder.build(), HttpResponse.BodyHandlers.ofInputStream())
        } catch (e: IOException) {
            throw NativeApiException(
                0, "transport",
                "$method $path failed (daemon down?): ${e.message}", true
            )
        } catch (e: InterruptedException) {
            Thread.currentThread().interrupt()
            throw NativeApiException(0, "transport", "$method $path interrupted", true)
        }
        val status = response.statusCode()
        val text = response.body().use { readBounded(it, maxBytes, "$method $path") }
        if (status !in 200..299) {
            throw apiError(status, text, "$method $path")
        }
        return text
    }

    /** Reads at most [maxBytes]; an oversized body is closed and rejected. */
    private fun readBounded(stream: InputStream, maxBytes: Long, path: String): String {
        val out = ByteArrayOutputStream()
        val buffer = ByteArray(8192)
        var total = 0L
        while (true) {
            val read = stream.read(buffer)
            if (read < 0) break
            total += read
            if (total > maxBytes) {
                throw NativeProtocolException(path, "response body exceeded bound $maxBytes bytes")
            }
            out.write(buffer, 0, read)
        }
        return String(out.toByteArray(), Charsets.UTF_8)
    }

    /** Maps a non-2xx body onto the daemon's typed error envelope. */
    private fun apiError(status: Int, body: String, path: String): NativeApiException {
        val parsed = try {
            JsonCodec.parse(body)
        } catch (e: NativeProtocolException) {
            return NativeApiException(status, "http_error", body.take(REQUEST_ERROR_SNIPPET), false)
        }
        val error = (parsed as? JsonValue.Obj)?.fields?.get("error") as? JsonValue.Obj
        val code = ((error?.fields?.get("code")) as? JsonValue.Str)?.value
        val message = ((error?.fields?.get("message")) as? JsonValue.Str)?.value
        val retryable = ((error?.fields?.get("retryable")) as? JsonValue.Bool)?.value
        if (code == null || message == null) {
            return NativeApiException(status, "http_error", body.take(REQUEST_ERROR_SNIPPET), false)
        }
        return NativeApiException(status, code, message, retryable == true)
    }
}
